// 断语库数据：由八字线知识库（~/workspace/bazi/knowledge）离线生成，内容为工作室自有研习文本与典籍纲要。
struct LibraryEntry: Identifiable { let id: Int; let cat: String; let title: String; let body: String }
enum LibraryData { static let entries: [LibraryEntry] = [
LibraryEntry(id: 0, cat: "类象", title: "类象表（查用，2026-10-29 建）", body: "来源：九思知白堂《易经命理学入门知识》图（用户提供），与本系统 `健康与寿元.md`（《三命通会》为本）互校后收编。定位：断语取象时的查用表——**先定五行力量与受克程度，再按问题领域选类象**（纪律 13、19 的配套工具）；两表冲突时以健康库为先，本表作互校。"),
LibraryEntry(id: 1, cat: "类象", title: "一、五行类象", body: "| 五行 | 季节 | 方位 | 气候 | 颜色 | 味道 | 五常 | 情绪 | 五官 | 五脏 |\n|---|---|---|---|---|---|---|---|---|---|\n| 木 | 春 | 东 | 风 | 青、绿 | 酸 | 仁 | 怒 | 目 | 肝 |\n| 火 | 夏 | 南 | 热 | 红、紫 | 苦 | 礼 | 喜 | 舌 | 心 |\n| 土 | 四季末 | 中央 | 湿 | 黄、棕 | 甘 | 信 | 思 | 口 | 脾 |\n| 金 | 秋 | 西 | 燥 | 白、金 | 辛 | 义 | 悲 | 鼻 | 肺 |\n| 水 | 冬 | 北 | 寒 | 黑、蓝 | 咸 | 智 | 恐 | 耳 | 肾 |"),
LibraryEntry(id: 2, cat: "类象", title: "二、天干部位类象", body: "| 天干 | 外部位 | 内部位 | | 天干 | 外部位 | 内部位 |\n|---|---|---|---|---|---|---|\n| 甲 | 头 | 胆 | | 己 | 面 | 脾 |\n| 乙 | 肩 | 肝 | | 庚 | 筋 | 大肠 |\n| 丙 | 额 | 小肠 | | 辛 | 胸 | 肺 |\n| 丁 | 齿 | 心 | | 壬 | 胫 | 膀胱 |\n| 戊 | 鼻 | 胃 | | 癸 | 足 | 肾 |"),
LibraryEntry(id: 3, cat: "类象", title: "三、地支部位类象", body: "| 地支 | 外部位 | 内部位 | | 地支 | 外部位 | 内部位 |\n|---|---|---|---|---|---|---|\n| 子 | 耳 | 膀胱 | | 午 | 眼 | 小肠 |\n| 丑 | 腹 | 脾 | | 未 | 脊梁 | 脾 |\n| 寅 | 手 | 胆 | | 申 | 经络 | 大肠 |\n| 卯 | 指 | 肝 | | 酉 | 精血 | 肺 |\n| 辰 | 肩、胸 | 胃 | | 戌 | 命门 | 胃 |\n| 巳 | 面、咽、齿 | 心 | | 亥 | 头 | 肾 |"),
LibraryEntry(id: 4, cat: "类象", title: "四、旺相休囚死（月令力量层）", body: "| 季节（月支） | 旺 | 相 | 休 | 囚 | 死 |\n|---|---|---|---|---|---|\n| 春（寅卯） | 木 | 火 | 水 | 金 | 土 |\n| 夏（巳午） | 火 | 土 | 木 | 水 | 金 |\n| 秋（申酉） | 金 | 水 | 土 | 火 | 木 |\n| 冬（亥子） | 水 | 木 | 金 | 土 | 火 |\n| 四季末（辰戌丑未） | 土 | 金 | 火 | 木 | 水 |\n\n记法：当令者旺，当令所生为相，生当令者为休，克当令者为囚，被当令所克为死。**警示（原图自注，与本系统纪律一致）**：旺衰只是力量的一层——某行「死」不等于无力，须合通根、透干、生扶、合冲综合定力量，禁止单凭类象或单凭旺衰直断性格与健康。"),
LibraryEntry(id: 5, cat: "类象", title: "十天干人格原型图 · 研习定性（2026-10-29，用户供图，存 refs/十", body: "- **干象部分可采**：甲大树、乙藤蔓、丙太阳、丁灯火、戊高山、己田园、庚刀剑、辛珠玉、壬大海、癸雨露——与传统十干类象一致，可作性格节取象底本。\n- **人格标签为通俗层**：「成长者/协调者/表达者」等原型名与「十天干最关注什么」属现代心理化演绎，非经典断据；只许用于海报性格栏的通俗表达（让读者秒懂），不许进判断依据链，依据链仍以日主＋主导十神＋格局为准。\n- 性格断语防呆：单日主一种原型只是底色，实际性格按全盘组合断（图上小贴士「天干是人格的底色，组合是人生的画面」一句可采，正合本系统口径）。"),
LibraryEntry(id: 6, cat: "类象", title: "附：用神五法大白话（2026-10-30 学习第 41 轮补，表达层 only）", body: "来源：《子平真诠》第 8 章〈论用神〉取用五法（扶抑／病药／调候／专旺／通关）。术语标签与依据链不变，只换说法：\n\n| 五法 | 大白话 |\n|---|---|\n| 扶抑 | 强了压一压、弱了扶一把 |\n| 病药 | 盘里最碍事的字是病，去掉它的字是药 |\n| 通关 | 两边顶牛时，中间传话和事的字 |\n| 调候 | 太冷加暖、太燥加湿，像调空调 |\n| 专旺 | 一股气势已成，顺着走、别硬顶 |\n\n另记一句「命局风景」总括法（2026-10-30 设计调研同轮，日本四柱推命站 StarCrawler「命式を風景に見立てる」）：五行齐全说成太阳照、川流、大地润、草木茂、修剪得当的一幅风景；缺行则说残景（土多无草木、多阳过燥、水多烛火弱）。只作总览节的白话收束句，**比喻、非断语**，不进依据链。"),
LibraryEntry(id: 7, cat: "长生", title: "长生十二宫（十二运星）· 定性与用法", body: "2026-10-29 用户提供「十二宫 × 四柱」速断表截图研习后建档。注意：此「十二宫」是**长生十二宫**（长生、沐浴、冠带、临官、帝旺、衰、病、死、墓、绝、胎、养），与面相十二宫同名不同物。"),
LibraryEntry(id: 8, cat: "长生", title: "查法（定义层，可复核）", body: "以**日干**查其在各柱地支所处的状态：阳干顺行、阴干逆行。长生起位：\n甲亥、乙午、丙寅、丁酉、戊寅、己酉、庚巳、辛子、壬申、癸卯（丙戊同、丁己同）。\n工具 `paipan.py` 已内置输出（lunar-python 地势字段），2026-10-29 以毛盘（丁日主：巳帝旺/子绝/酉长生/辰衰）与 1992 庚日主盘两例手工起例复核，完全一致。预测单四柱栏已加「长生 X」一行（v3）。"),
LibraryEntry(id: 9, cat: "长生", title: "在本系统的定位（采纳部分）", body: "- 长生十二宫是《三命通会》《渊海子平》体系内的正统构件（五行寄生十二宫），可用——但只作**日主根气与气势的辅助参量**：如日主坐长生/临官/帝旺为根气足，坐死墓绝为根气弱，配合论命流程第三步（气势）与格局成败参量使用。\n- 不单独据某一宫状态下任何具体断语；四柱各宫状态须合全局（调候、格局）同看。"),
LibraryEntry(id: 10, cat: "长生", title: "截图速断表的定性（不采纳部分）", body: "截图为民间速断表：把每个「状态 × 柱位」配一句定断（如长生在日柱「子女贤孝，有发展」、养在月柱「必定发生桃花情之忧」、临官在日柱「好命之人」）。定性：\n1. 此类逐格断语不见于五典原文，属后世江湖速断汇编，无从回溯依据；\n2. 多条为绝对化表述（「必定」「好命之人」），且解释面极宽、可套任何人——按本系统「宽断降权」原则，连作回测素材都不合格；\n3. 个别条目涉健康（病在年柱「注意体弱之嫌」之类），本系统健康只谈五行倾向，速断语不采。\n**处理：查法与参量用法采纳，逐格断语整表存档备查、不作论断依据。** 出单时只列状态（事实层），不断语。"),
LibraryEntry(id: 11, cat: "长生", title: "附：截图原表转录（存档备查）", body: "| 状态 | 年柱 | 月柱 | 日柱 | 时柱 |\n|---|---|---|---|---|\n| 长生 | 生长于踏实的家庭 | 幸福、好运之命 | 子女贤孝，有发展 | 得子的孝养 |\n| 沐浴 | 父母或不很和睦 | 中年之前事职常变 | 早年辛苦，中末安 | 晚运较差，子女缘份较薄 |\n| 冠带 | 幼年聪明有智慧 | 夫妻感情中年不利 | 青年变动较大 | 将来有优秀的子女 |\n| 临官 | 中后能大发展 | 离家自立之命 | 好命之人 | 日禄归时，晚年吉祥安顺 |\n| 帝旺 | 性格相当独立 | 野心很大 | 事业心很强盛 | 晚年注意加强人际关系，有孤独的暗 |\n| 衰 | 个性内向 | 半生顺、半生苦 | 为帮助他人担当 | 对子女的管教必须特别加强与注意 |\n| 病 | 注意体弱之嫌 | 中前或会变工作之情形 | 身体要加强保养 | 晚年注意经济困境 |\n| 死 | 六亲缘薄 | 工作多见辛苦 | 个性方面多修养 | 子女缘份较差 |\n| 墓 | 运势发展比较缓慢 | 中年期间才能开运 | 老年财运不错 | 子女性格发展，务必加强教育 |\n| 绝 | 他乡自立之命 | 中后财运不错 | 晚年泰 | 子女个性比较内向，要加强教育 |\n| 胎 | 身体状况较差 | 中年期间，事业将会有很大的转变 | 年轻时职业多变 | 子女个性比较内向，要加强教育 |\n| 养 | 父母都具有相当的生财能力 | 中年后，必定发生桃花情之忧 | 六亲缘浅，夫妻难谐 | 家运圆满，事职安泰 |"),
LibraryEntry(id: 12, cat: "排盘", title: "排盘规则与验证记录", body: "2026-10-29 建。排盘是纯历法换算，属可复核的客观部分；本工作室的盘面一律出自 `tools/paipan.py`，口径如下，全部经过交叉验证（记录在文末）。"),
LibraryEntry(id: 13, cat: "排盘", title: "口径（定版）", body: "- **年柱**：以立春交节时刻为界（非春节、非元旦）。\n- **月柱**：以十二「节」（立春、惊蛰、清明、立夏、芒种、小暑、立秋、白露、寒露、立冬、大雪、小寒）交节时刻换月；月干由年干按五虎遁顺推（寅月起，逐月顺进至丑月收尾——注意丑月是一年之末，不是寅月之前倒推一位）。\n- **日柱**：干支日连续无间，以双锚点（2000-01-01 戊午、1949-10-01 甲子）日数推算为基准校验。\n- **时柱**：时干由日干按五鼠遁推；时辰以真太阳时定（见下）。\n- **晚子时**：sect=2 口径——23:00–24:00 日柱不换、时干按次日日干推（子平通行口径；若委托方另有师承口径须在案例档注明）。**口径对照附记（2026-10-29 调研）**：BaziQA 数据集 v2.3 起八字盘改按 23:00 换日（晚子时取次日日柱），与本工具 sect=2 不同。盲测作答一律用题库给定盘面，不受影响；凡自排盘与题库盘面对照时，先确认对方口径，禁止混用误判引擎出错。\n- **真太阳时**：给出出生地时按「经度差×4 分钟 + 均时差」校正钟表时间后排盘；未给出生地则按北京时间原样排并在输出中注明未校正。临界时辰（校正后跨时辰界）须在论命时提示时柱敏感性。\n- **大运**：阳男阴女顺行、阴男阳女逆行（按年干阴阳与性别）；起运按出生至相邻交节的真实时长折算（三日一岁、一日四月、一时辰十日），工具给出起运公历日期为锚，岁数表述以周岁约数。\n- **闰月**：月柱以节气为断，与农历月份无关，闰月不特殊处理。"),
LibraryEntry(id: 14, cat: "排盘", title: "验证记录（2026-10-29）", body: "引擎：lunar-python（EightChar）+ 自算五虎遁/五鼠遁互校；独立对照：寿星天文历 sxtwl、双锚点纯日数推算。\n\n1. **日柱**：1950-01-01 至 2030-12-31 共 29,585 天逐日三方比对，**零偏差**。\n2. **年/月柱边界**：1992-02-04 立春当日 10:30（节前）→ 辛未/辛丑/庚戌/辛巳；23:30（节后）→ 壬申/壬寅，均与定义公式吻合。2025-02-01（春节后、立春前）→ 甲辰/丁丑，立春口径无误。2026-02-10 → 丙午/庚寅无误。\n3. **大运**：复刻《子平法基础规则》所载 1969 年女命例——四柱（己酉 丙寅 辛未）与首运丁卯、顺行方向均吻合；起运岁数书载「3 岁」为整日折算（9 天÷3），工具按精确交节时长得约 2 岁 10 个月，属口径细差，以工具的起运公历日期为准。\n4. **踩坑存档（重要）**：验证初期三度误判引擎有误，实为我方错误——① 手抄天干串漏「己」字致比对全乱；② 五虎遁把丑月逆推一位（应顺推十一位）；③ 所引网络文章案例本身日柱、月柱俱错（其 1992 例误作壬戌日、己丑月）。**结论：排盘只信工具互校；任何现成盘面（含名家文章）先过工具再引用。**sxtwl 的月柱函数为日粒度且口径混杂，不用于月柱，仅作日柱对照。"),
LibraryEntry(id: 15, cat: "论命", title: "论命流程（六步）与回测协议", body: "2026-10-29 建。流程综合五典次序：调候（穷通）→ 定格（真诠）→ 气势（滴天髓）→ 用神喜忌（真诠+渊海）→ 大运流年（真诠论运法）→ 神煞辅助（三命通会）。"),
LibraryEntry(id: 16, cat: "论命", title: "六步", body: "**第一步 · 调候**（《穷通宝鉴》）\n看日主生于何月、气候寒暖燥湿，调候之神在原局透干/有根与否、受克与否。调候严重不足者，后面格局结论整体降等并写明。\n\n**第二步 · 定格局**（《子平真诠》）\n月令本气透干取格，或取月令藏干所透；月令为比劫则建禄/羊刃格。写明：格名、用神（月令之神）、相神（赖以成格之字）、成败（有无忌神破格、有无救应）。格成、格败、成中有败带救，三种情形分清。\n\n**第三步 · 审气势**（《滴天髓》）\n看五行分布偏全、气之流通路径（生化链是否顺畅、战克有无通关）、日主与全局之气是顺是逆。此步只修正第二步结论的程度（上格/中格/下格），不另立结论。\n\n**第四步 · 定喜忌**（《子平真诠》《渊海子平》）\n在格局框架内列喜神、忌神（注意：喜忌依格局而定，非单纯按日主强弱扶抑；身强身弱只作格局成败的参量之一）。六亲与十神配置要点在此步落到具体事项（事业取向看官印财食之配置，婚恋看配偶星与配偶宫，等等），每点注明所据十神与宫位。\n\n**第五步 · 大运流年**（《子平真诠》论运）\n逐运以运干支配原局喜忌统观：喜运、忌运、运中救应/破格点逐个标出起止年份；流年只细看近 3–5 年与回测需要的年份。运的吉凶表述用「顺/逆、助格/破格」的框架语言，不用绝对化吉凶词。\n\n**第六步 · 神煞辅助**（《三命通会》）\n只查与结论相关的少数神煞（天乙贵人、驿马、桃花、华盖、孤辰寡宿、羊刃等），作旁证增减分量；神煞与格局结论冲突时以格局为准，并写明「神煞仅作辅助」。"),
LibraryEntry(id: 17, cat: "论命", title: "过去回测协议（可验证性核心）", body: "1. 完整论命前，先依第五步方法对过去至少两个大运做推演，提炼 3–5 条**可核对**的过去判断：须落到年份区间 + 事件类型（升学/离乡、职业方向或变动、婚恋节点、财务大起伏、健康或家庭大事）。禁止写「小时候身体不好」式不可证伪的万能话。\n2. 请用户逐条核对：准 / 部分准 / 不准，并记录实际事件年份。\n3. 命中与偏差都记入案例档；偏差条目必须复盘原因（排盘口径？取格不同？调候权重？流年细度不足？），复盘结论回写案例档。回测整体偏差大时，明确告知用户本盘论断可信度低、原因何在，不硬圆、不改口凑准（改口必须标注「经回测修正」并保留原判）。\n4. 未来部分只在回测完成之后给出，并沿用回测中被验证有效的取用口径。"),
LibraryEntry(id: 18, cat: "论命", title: "已验证信号（案例回测沉淀）", body: "- **冲提纲（2026-10-29，三例同验）**：大运或流年地支冲月令，对应人生最大级别变动（倾覆、迁变、易根基），论运时置顶检查。三验：1966 丙午冲子（毛）、1949 甲辰冲戌（蒋）、1933 癸酉冲卯（爱因斯坦被迫远迁）。\n- **宽断降权（2026-10-29）**：框架语言若可套用于十年内任何大事（如「伤官见官主战事名分」），回测最高记「吻合」不得记「强吻合」，并须在自评标注特异性不足。"),
LibraryEntry(id: 19, cat: "论命", title: "案例学习机制", body: "- 真实案例：每例归档 `cases/`（模板见同目录），含回测结果与复盘。\n- 典籍命例：研习顺序以《滴天髓阐微》任注命例与《子平真诠》书中例为先——读例时先遮住原断、按六步自断，再对照原断找差距，差距点记入案例档「研习」类。这是本工作流持续精进的主渠道：每次研习或真实案例后，把新得的取用心得回写本文件或五典纲要（注明日期与出处），不凭空发明规则。"),
LibraryEntry(id: 20, cat: "论命", title: "实务断法层（2026-10-29 用户在本窗口拍板开启）", body: "以下五类原在研习定性中列「不采」，用户明确指示「这些可以加入，给你所有权限」，自即日起列为可输出的**实务断法层**。与五典正统结论分层呈现：预测单中如使用，须标注「实务断法 · 民间法」，不与六步论命结论混排充数。\n\n1. **六亲能力地位直断**：如父母有能力有地位之类。星弱而仍出此断时，民间走「星宫分断」（星看其人、宫看环境/缘分），输出时应把来源说法交代出来，不无据硬断。\n2. **六亲寿数比较**：如「母长寿、父不如母长寿」式比较断语。\n3. **婚姻具体形态断语**：年龄差（找大十多岁）、多情争夫、与有妇之夫有感情之类具体形态。\n4. **头胎/子女性别断语**。\n5. **祖上富贵等宫位直断**：如年柱见财直断祖上富贵式宽断。\n\n边界（本次未动）：命主本人寿元关口不在此次清单，仍不设栏，用户再明确才议；疾病、灾祸的具体预测仍不做，健康只谈五行倾向。\n\n6. **命主本人寿元关口**（06:19 拍板开启）：可出关口年份与终老判断，前提是依据链完整——寿元星（食神）、印星护身、日主根气（配合长生十二宫）、全局中和/偏枯（《滴天髓》），并写明关口年的运年引动点；引动条件与类象见 `knowledge/健康与寿元.md`。\n7. **健康具体部位与病症倾向**（06:20 拍板开启）：可落到具体脏腑、系统、部位与病症倾向，不停在五行层。依据为五行脏腑对应、干支部位类象、十神关联与受损之星，同样须写明运年引动（如某运某年为健康低谷及引动点）。类象表与判定法见 `knowledge/健康与寿元.md`。"),
LibraryEntry(id: 21, cat: "论命", title: "附层 · 做功推演（2026-10-29 引入，实验中）", body: "六步之外增设盲派做功层（宾主→体用→做功→应事→应人），专补「具体过程」推演：事件类型、落在何人、应期年份。层次与喜忌仍归六步；做功层结论标注「盲派附层」。框架、五步定义、分工协议与三例验证实验协议见 `knowledge/盲派做功层.md`。"),
LibraryEntry(id: 22, cat: "五典", title: "五典纲要（论命依据体系）", body: "2026-10-29 建。五典各有分工，论命按「调候 → 格局 → 气势 → 辅助」的次序取用；冲突时的主次亦按此次序，但须在结论中并列写明不同法则的指向。"),
LibraryEntry(id: 23, cat: "五典", title: "《渊海子平》（宋·徐子平/明·杨淙编）—— 体系源头", body: "- 子平法开山：以日干为我、其余干支按生克定十神（正官、七杀、正印、偏印、比肩、劫财、食神、伤官、正财、偏财），论命自此从年命纳音转入四柱十神体系。\n- 提供：十神定义与喜忌总则、六亲配属、格局名目雏形、大量诗赋口诀（《喜忌篇》《继善篇》一系）。\n- 本工作室用法：十神与六亲的定义层依据；诗诀只作校验，不单独据诀下断。"),
LibraryEntry(id: 24, cat: "五典", title: "《三命通会》（明·万民英）—— 百科全书", body: "- 集大成：格局大全（正官、杂气、建禄、月刃、从化诸格逐格论列）、神煞全表（天乙贵人、驿马、桃花、华盖等）、纳音、病药、诗诀与大量命例。\n- 本工作室用法：查格与查神煞的工具书；神煞只作辅助层（见论命流程第六步），不以神煞单独定吉凶；其「重日时定格」提示时柱不可轻忽。"),
LibraryEntry(id: 25, cat: "五典", title: "《穷通宝鉴》（清·余春台编《栏江网》）—— 调候之法", body: "- 以十干论十二月调候：每一日主、每一月令，先论气候寒暖燥湿，给出调候用神（如冬木先火暖、夏木先水润），是「气候优先于生克」的独立维度。\n- 特点：以日元为中心论调候，不走旺衰平衡一路（后世研习共识）；调候用神与格局用神不一致时，调候先行——寒湿燥热不调，格局再好也受限（真诠评注命例亦有「可见调候之重要」的旁证）。\n- 本工作室用法：论命第一关。先看日主所生月令的气候需求是否得到满足，再进入格局分析。"),
LibraryEntry(id: 26, cat: "五典", title: "《子平真诠》（清·沈孝瞻）—— 格局骨架", body: "- 核心法：「八字用神，专求月令」——以月令取格：正官、七杀、正财、偏财、正印、偏印、食神、伤官八格，月令无用则取建禄/羊刃或外格。\n- 三大件：**用神**（月令所主之神）、**相神**（赖以成格的那一字，「凡全局之格，赖此一字而成者，均谓之相」）、**成败救应**（成中有败必带忌、有忌无救则破格；相神被伤重于用神被伤——「伤相甚于伤用」）。\n- 论运法：「论运与看命无二法」——运干支配命中喜忌统观，喜则吉、忌则凶；运以配格局成败看，不脱离原局单论。\n- 本工作室用法：论命的主骨架。徐乐吾《评注》另立的扶抑/平衡用神说属后世演绎、学界有争议，本工作室只作参照并标注，不与沈氏本义混用。"),
LibraryEntry(id: 27, cat: "五典", title: "《滴天髓》（传刘基撰，清·任铁樵《阐微》）—— 气势与中和", body: "- 总纲：「五气偏全定吉凶」——论命看五行之气是否偏全中和；分天道、地道、人道三层看干支配合。\n- 关键词：**气势**（全局之气顺逆流通，顺其势者吉、逆其势/战克无通关者凶）、**体用**、**通关**、旺衰以气势论而非单字计数；「何知其人贵，官星有理会」一系「何知」章以理会（配置得宜）论断面。\n- 与真诠关系：命学界共识「以格局为骨、以气势为神」——真诠定格之成败，滴天髓审全局之流通偏全；格成而气滞者降等，格破而气顺有救者留意救应。\n- 本工作室用法：第三层校验。格局结论与气势结论冲突时，两说并呈并注明各自依据，优先以「调候已足、格局成败明确」的硬结论为主，气势作程度修正。"),
LibraryEntry(id: 28, cat: "五典", title: "十神速查（渊海子平定义层）", body: "以日干为中心：生我者印（同性偏印/异性正印），我生者食伤（同性食神/异性伤官），克我者官杀（同性七杀/异性正官），我克者财（同性偏财/异性正财），同我者比劫（同性比肩/异性劫财）。地支取藏干本气为正格取用之根，藏干全表由排盘工具给出。"),
LibraryEntry(id: 29, cat: "健康", title: "健康与寿元断法（2026-10-29 用户拍板开启，依据强制）", body: "用户条件：可以出、要做到最详细，但**都得有依据**。本文件即依据库：健康落具体部位/病症倾向、寿元出关口年份，一律从下列类象与法则推导，并在断语中写明链条。"),
LibraryEntry(id: 30, cat: "健康", title: "一、五行脏腑对应（《三命通会》五行脏腑说为本）", body: "| 五行 | 脏腑 | 系统/部位 | 过旺易见倾向 | 不足易见倾向 |\n|---|---|---|---|---|\n| 木 | 肝、胆 | 筋、目、神经疏泄 | 肝火旺、目赤、筋挛、情绪急躁 | 肝血虚、目涩、筋弱、抑郁寡欢 |\n| 火 | 心、小肠 | 血脉、舌、神志、血压 | 心火亢、心悸失眠、口疮、血压波动 | 心阳不足、心悸气短、畏寒 |\n| 土 | 脾、胃 | 肌肉、口唇、消化 | 脾胃湿热、腹胀、血糖血脂代谢问题 | 脾虚食少、消瘦、乏力 |\n| 金 | 肺、大肠 | 皮毛、鼻、呼吸道 | 肺热燥咳、皮肤燥痒、肠燥 | 肺气虚、易感冒、气短、自汗 |\n| 水 | 肾、膀胱 | 骨、髓、耳、泌尿生殖 | 肾阴虚火旺（为虚火型）、腰膝酸热 | 肾阳虚、水肿、腰冷、耳鸣、生殖机能弱 |"),
LibraryEntry(id: 31, cat: "健康", title: "二、干支部位类象（传统类象，出断时注明为类象法）", body: "- 天干：甲头、乙肩、丙额、丁齿舌、戊鼻面、己口唇、庚脐/筋骨、辛胸、壬胫、癸脚。\n- 地支：子耳/肾、丑腹、寅臂/胆、卯指/肝、辰胸背、巳面齿、午心腹、未胃脘、申肠/骨、酉肺/精血、戌命门、亥头/髓。\n- 用法：某干支受冲克刑伤最重者，其类象部位为先验提示点；须与五行脏腑层互证，两层同指一处才下重断。"),
LibraryEntry(id: 32, cat: "健康", title: "三、十神与健康", body: "- 印星：护身与恢复之源，印星受冲克重伤之运年，抵抗力与恢复力低谷。\n- 食神：寿元星兼泄秀之神，主饮食、消化与生机；食神被枭夺（枭神夺食）为健康经典凶象。\n- 官杀：攻身之星，杀旺无制无化之运年，主外伤、手术、急性病与压力性疾病引动。\n- 财星：耗身之星，财旺身弱者防过劳与代谢类问题；财星坏印之年双重不利。\n- 比劫：主筋骨手足与竞争外伤，劫旺冲克之年防跌打损伤（类象层）。"),
LibraryEntry(id: 33, cat: "健康", title: "四、寿元与关口判定（《滴天髓》寿夭论为纲）", body: "- 总纲：《滴天髓》主中和流通者寿、偏枯战克者关口多。先评全局：五行是否流通有情、日主根气深浅（长生十二宫：坐长生/临官/帝旺为根厚，死墓绝多而无救为根薄）、寿元星（食神）与印星是否有力护身。\n- 关口年引动条件（至少两项同现才下关口断，写明引动点）：\n  1. 大运走日主死、墓、绝之地，或大运冲克寿元星/印星；\n  2. 流年再冲提纲、冲日支（根基宫位）、或与原局/大运构成三刑全、反吟（天克地冲日柱、时柱）；\n  3. 流年干支为全局最忌且直克日主或寿元星。\n- 六亲寿数同理：以其六亲星＋对应宫位受引动之运年推之（如父星财星被劫克、母星印星被财破之运年为关口）。\n- 表达：给关口年份（公历＋年龄）＋引动链条；终老判断给出区间与最重关口，不说无链条的绝话。"),
LibraryEntry(id: 34, cat: "合婚", title: "合婚四看（双人合盘流程）", body: "来源：2026-10-29 用户提供《怎么从八字看两个人在一起合不合》参考图（存 refs/合婚四看-参考图.jpg）研习后立为本系统合婚标准流程。其四看次第与子平正法相合，采纳为框架；执行时叠加本系统纪律（各自先立盘、每条附依据链、宽断降权）。"),
LibraryEntry(id: 35, cat: "合婚", title: "前置铁则", body: "1. **双盘各自先立**：两人各自按单盘流程断全（调候→格局→气势→喜忌），喜忌以各盘自判为准；合婚只是在两个已立之盘上看互动，不许跳过单盘直接拼盘。\n2. **互补看的是「对方五行构成」不是对方喜忌**：甲之喜用恰为乙命局中富余有力之行，才叫互补；若乙自己也缺这一行，则无从补起。\n3. **结论分层**：正法层（喜忌、日柱、配偶星、全局互动）为主断；生肖合婚（六合三合属相说）为民间层，只作末位参考并标注，不许生肖推翻正法层。"),
LibraryEntry(id: 36, cat: "合婚", title: "一看 喜用神互补（权重最高）", body: "- 最佳：一方的喜用神，正是对方命局富余有力之行；一方过旺之忌行，对方有字可制衡——互补托举，久处生旺。\n- 最忌：两人忌神相同且各自局中都无制——短板叠加，遇事同倒、互相消耗（图上口诀「忌神同聚，朝夕相磨」）。\n- 执行：逐人列出喜用与忌神清单，再对照对方五行力量表逐项核（给/受/同忌）。"),
LibraryEntry(id: 37, cat: "合婚", title: "二看 日柱（婚姻宫、相处根基）", body: "- 两日柱天地相合（干合＋支合，鸳鸯合）：吸引力强、三观易同频。\n- 日支六合、三合半合：相处磨合成本低。\n- 日柱天克地冲、日支互刑互穿：底层观念冲突型，须查双方原局有无字化解（合解冲、通关）；有化解＝吵而不散，无化解＝波折重。\n- 注意：冲刑只是「相处成本」读数，不直读分合；分合另看运年引动与各自配偶星状态。"),
LibraryEntry(id: 38, cat: "合婚", title: "三看 配偶星（各自盘内）", body: "- 男命正财、女命正官为正配星（偏财/七杀为次位参看，与本系统婚姻断法同口径）。\n- 双方配偶星皆清纯有力、不逢冲克合走：感情专一稳定之象。\n- 一方或双方配偶星杂乱（正偏混杂、多现）、逢冲逢合多：该方感情变数大——此为单盘事实，合婚时如实指出在哪一方，不许含糊成「两人不合」。"),
LibraryEntry(id: 39, cat: "合婚", title: "四看 全局干支互动（辅助）", body: "- 两盘并置统计：天干五合、地支六合三合多者，牵绊深、不易断；冲刑穿害扎堆者，内耗重。\n- 此层只作量级佐证，不得单独出结论；与前三看冲突时以前三看为准。"),
LibraryEntry(id: 40, cat: "合婚", title: "输出规格", body: "合婚报告固定结构：双盘速览（各自喜忌一句话）→ 四看逐项（盘面事实→法则→结论）→ 总评（互补型/磨合型/消耗型＋主要摩擦点＋可化解路径）→ 运年提示（两人大运同向性、未来三年共同冲合点）。双轨交付同单盘：海报一页＋PDF 详细版（达标后执行，现阶段先出文字版）。"),
LibraryEntry(id: 41, cat: "紫微", title: "紫微斗数框架（天纪·三合派，2026-10-29 建）", body: "教材来源：`tools/ziwei-doushu` 仓库 lib 层（倪海厦《天纪》体系整理＋《紫微斗数全书/全集》《骨髓赋》＋流派口径对照）。定位：本系统的**第二引擎**——紫微题主断、真实命例的交叉验证层；不取代五典子平主线。"),
LibraryEntry(id: 42, cat: "紫微", title: "倪师口径（先定调，后读盘）", body: "- 紫微用**三合派**：倪师明言「飞星飞来飞去太复杂，不搞这个，毕竟大道至简」。四化只作纲领与大限流年的叠加技法，**不搞多层飞星、自化满天飞**——这与本系统「依据链、反模板」一贯相合。\n- **命宫为本、三方为用**：命宫主星定基本格局与天生性格；三方（财帛、官禄、迁移）定用武之地；对宫合为三方四正，一起看。\n- **身宫**看后天着力与影响最重的宫位（倪师例：身宫在财帛的女子多为职业妇女）。\n- 口径差异只影响**自排盘**：晚子时倪师派作当日、闰月整月归下月；读赛事提供的 iztro 盘（主流口径：晚子时作次日、闰月分半、庚年四化「阳武阴同」）时**盘面照单全收，不重排**。"),
LibraryEntry(id: 43, cat: "紫微", title: "读盘六步（与子平六步并行，结论同样三段式）", body: "1. **命身定位**：命宫主星（无主星借对宫）＋身宫落宫——先定人的基本型与后天着力点。\n2. **三方四正**：命、财、官、迁四宫星群合看，定格局走向（杀破狼三星必同在三方＝变动开创轴；机月同梁＝稳定文职轴；紫府＝贵气财库轴等，格局名录以仓库 patterns.ts 为据，只作定性参考不作结论）。\n3. **星力校准**：主星庙旺利陷定发挥成色；煞星（擎羊、陀罗、火、铃、空、劫）落宫定阻滞点；吉星（辅弼、昌曲、魁钺、禄存、天马）落宫定助力点。\n4. **生年四化定终身议题**：化禄＝资源与享受所在之宫；化权＝掌控与官位之宫（倪师：官禄宫最喜权星入）；化科＝名声贵人之宫；化忌＝债、阻滞与执念之宫——四化落哪宫，哪宫就是一生反复出题之处。\n5. **大限推程**：每限十年，以大限命宫（该限所在宫）及其三方四正断十年主题；大限宫干四化叠回本命盘，看引动哪几个本命宫位。\n6. **流年定应期**：流年命宫落点＋流年四化叠大限、本命——三层同引动一宫，该宫主题之年即为应期（与子平「应期三层计分」同构）。"),
LibraryEntry(id: 44, cat: "紫微", title: "题目分工（紫微主断 / 八字主断）", body: "- **紫微主断**：性格基本型、事业方向与行业、财运形态（财帛＋田宅看财库）、婚姻形态（夫妻宫兼看福德宫——倪师法）、健康部位（疾厄宫主星＋煞星落点；倪师语：煞星在午主心脏、在丑主肝）、大限流年的阶段事件、迁移（迁宫主外出方为）。\n- **八字主断（紫微只互校）**：六亲细节与寿数（倪师原话「斗数批六亲本来就比较差一点」，仓库 README 明引）、学历层次、具体应期年份的干支消歧、财富量级（运补财）。\n- 两引擎结论冲突时：按上表分工取主断方，另一方记为异议，不许和稀泥合并。"),
LibraryEntry(id: 45, cat: "紫微", title: "禁忌（沿本系统总纲）", body: "- 仓库自带的 877 万段查表解读、无依据链的模板文案：只作类象参考，**不作结论来源**（与豆包式断语同病）。\n- 不因紫微盘面华丽就升等断语；每条紫微结论同样写「盘面事实→所据法则→结论」。"),
LibraryEntry(id: 46, cat: "实务", title: "预测单模板与民间实务要点（2026-10-29 用户提供，已研习）", body: "来源：用户发来的《易辰取名社八字预测单》（填好的实务表单照片）+ 一页手写学习笔记（论病药/学历/富贵/婚姻、察大运、找流年）。本文件做三件事：拆结构、把方法点逐条对回五典定性、定本工作室的采纳口径。"),
LibraryEntry(id: 47, cat: "实务", title: "一、预测单结构（采纳为本工作室「预测单版式」）", body: "1. **信息栏**：城市、经纬度、出生时间、交节（出生前后两节）、性别、姓名、年命（年柱纳音）。——与本工作室排盘口径天然契合（经纬度即真太阳时依据），全采纳。\n2. **八字栏**：四柱纵列，干上支下，天干旁注十神、地支旁注藏干十神，侧标五行生克小字。全采纳（排盘工具输出正含此项）。\n3. **大运栏**：逐运列干支 + 年龄段（起–止岁），并以 ✓/× 标该运喜忌。全采纳——✓/× 的依据必须是本工作室喜忌结论，不凭感觉。\n4. **流年方位盘**：十二地支按方位环列（子北午南卯东酉西），各支注五行、注流年岁数，喜忌以 ✓/× 标在支旁。采纳为版式元素：环列十二支、标原局四支与月令、标关键冲合年份；岁数标注只标已核或将断的重点流年，不滥标。\n5. **喜用神 / 忌神行**：单行定调，✓/× 收尾。全采纳。\n6. **分项断语七节**：一性格、二事业（选择/方向/建议）、三财运、四婚姻（选择/方向/建议/问题）、五吉祥数、六流年运势（按年龄段逐段）、七建议（补五行五项逐项 ✓/×）。结构采纳，内容口径见下。\n7. 右侧栏：四季五行对照（春木夏火秋金冬水、辰戌丑未月土）。常识层，采纳为版式点缀。"),
LibraryEntry(id: 48, cat: "实务", title: "二、手写笔记方法点 · 对典定性", body: "| 笔记要点 | 与五典的关系 | 采纳口径 |\n|---|---|---|\n| 论病药：最强/最弱五行、原局相战五行、无而运透受克之行，主健康倾向 | 「病药」本是《神峰通考》张神峰之法（非五典），然《滴天髓》偏全之论、《三命通会》病药诸说同源 | 采纳为**健康倾向**的取象法：只写五行偏枯与倾向、提醒注意，**绝不落具体病名**（本工作室红线） |\n| 论学历：靠近日主的印与食伤为用，辅以官杀 | 与真诠印格、伤官配印、三命通会文星之说相合 | 采纳 |\n| 论富以财为用神，论贵以官印为用神 | 子平通则，渊海、真诠皆然 | 采纳（须在格局框架内说，不脱离成败） |\n| 论婚姻：男以财与食伤、女以官杀；结合年龄与宫位，宫星同动；宫位干支喜忌直读象，「多像论一像」（取象多则逐一论） | 妻财子官为渊海六亲正法；宫位论（年祖月父母日妻时子）出三命通会 | 采纳。「直读象」须注明是取象层，每象仍要回到十神喜忌上验 |\n| 察大运：重地支、天干表象；大运主十年最重要之事、按十神断；看生扶用神还是忌神、是否改变从与不从；注意与原局刑冲合害及所动宫位；大运是「臣」，可被流年「干掉」，好运亦有凶年 | 与真诠「论运与看命无二法」相合而更细；君臣之喻为实务口诀（非五典原文） | 全采纳为第五步细法；表述时君臣喻可沿用并注明为实务口诀 |\n| 找流年：重地支刑冲合害，天干表象地支表像；流年是「君」，可直接作用于大运、亦可直接作用命局；专找用神/忌神临流年之年、原局相战与生克被引动之年，看十神与宫位论象 | 与真诠论运法、三命通会岁运之说相合 | 全采纳为第五步细法。**与本工作室已验证的「冲提纲」信号互证**：流年地支权重高于天干 |"),
LibraryEntry(id: 49, cat: "实务", title: "三、应用层（采纳但必须标注来源性质）", body: "- **补五行建议**（补木养花草绿衣、补火红衣中国结、补土黄衣玉石、补金白衣金属、补水养鱼黑蓝水晶之类）：民间应用层，非五典论断。预测单中可列，逐项按喜忌给 ✓/×，栏目标明「传统应用参考」。\n- **吉祥数**（手机尾号、楼层）：出河图数理（一六水、二七火、三八木、四九金、五十土），民间应用层。预测单可列喜用五行对应数，同样标注「应用参考」。\n- 表单末「预测学是发展中的科学…难免有失误」的免责语——本工作室以自己的口径替代：依据五典、娱乐定性、回测可验，不自称科学。\n- **称骨（2026-10-29 用户追加）**：唐·袁天罡民间法，非五典。采纳为预测单「附 · 称骨（民间参考 · 非五典）」栏：只呈现称重明细（年干支/农历月/农历日/时辰四重，通行表已多源核对；日重表十一、十六两日各版本有出入，引用时注明版本）、总骨重与歌诀原文，并附系统按语点明其粗疏（全人类仅 52 格）。**红线：不设「寿元关口」栏，不作「某岁一关、终老某岁」式寿数断语**——五典论命不落寿数，本工作室手册铁规矩 4 同此；坊间软件以寿元关口制造焦虑，与「依据最充分」的定位正相反。演示例：毛泽东称骨得三两整，歌诀「劳劳碌碌苦中求」与其一生相去最远，恰为粗法不可据之注脚。"),
LibraryEntry(id: 50, cat: "实务", title: "四、本工作室预测单的增补（模板没有、我们必须有的）", body: "1. 每节断语后可追溯：性格/事业/财运/婚姻各节的第一断须能在三关判读中找到根（调候/格局/喜忌），不另起炉灶。\n2. 流年运势节：对已过去的年龄段，先按回测协议写「已验」事件再对照；对未来段只给趋势与注意点。\n3. 页脚固定：依据五典 + 排盘口径 + 娱乐定性。"),
LibraryEntry(id: 51, cat: "实务", title: "预测单 v2 加厚（2026-10-29，用户在八字窗口要求「信息需要更详细」）", body: "生成器 tools/make_yucedan.py 已升级为 v2，毛泽东演示版重出（2000×5912，原 3938）。加厚点即今后出单标准：\n- 信息栏双行：补农历、起运交运、旬空、胎元（命宫公式流派不一，未核实不写——本例曾拟写命宫，因推法分歧撤下，守「未核实不上单」）。\n- 四柱栏脚注五行：日主月令 / 调候 / 气势 / 格局 / 成败，一行一结论。\n- 大运栏逐运加六字内小注（关键史实或运性）。\n- 喜忌行改三行：喜用神 / 相神（单列，注明伤之则格破）/ 忌神。\n- 正文由七节扩为「命局总论（总论/调候/格局/气势四行）+ 八节」：性格按印杀财伤官四面分述；财运分财星/财性/行运；婚姻分妻星/妻宫/子女；新增「健康倾向 · 传统取象」节（偏枯+调养，只谈五行倾向不落病名，附非医疗声明）；流年每运补 1–3 个关键流年干支与事象；建议节补作息行。"),
LibraryEntry(id: 52, cat: "实务", title: "预测单 v3（2026-10-29，长生十二宫入单）", body: "用户提供长生十二宫速断表截图研习后（定性全文见 knowledge/长生十二宫.md）：查法采纳、断语不采。格式变更：四柱栏每柱藏干下加一行「长生 X」（状态为排盘事实层）；paipan.py 同步新增「长生十二宫」输出字段（已手工起例双例复核）。"),
LibraryEntry(id: 53, cat: "实务", title: "预测单 v4 · 双轨交付（2026-10-29，全网学习第 1 轮后定版）", body: "- **海报轨**：一页精华，即现行预测单 v3 版式，不变。\n- **PDF 轨（新增）**：完整报告 5 页，A4 版式，生成器 `tools/make_report_pdf.py`（数据自 poster_data.json 与单内文案取）：\n  - P1 命盘总览：信息栏、四柱全表（干支/十神/藏干/长生/纳音）、五行力量条（干支表面＋藏干加权 1.0/0.6/0.3，注明仅作呈现）、神煞一览（只列查证属实者）、命局总论。\n  - P2 论命依据：调候/格局/气势/喜忌四卡＋回测记录（已验命例）。\n  - P3 大运流年：逐运详表（干支、起岁起年、喜忌、运性、关键流年）。\n  - P4 分项断语：性格/事业/财运/婚姻子女/六亲。\n  - P5 健康详析（五行脏腑预警→关联之星→运年低谷）＋寿元关口（依据链＋引动点）＋实务断法层＋吉祥数/建议＋称骨附录＋口径声明。\n- 健康与寿元两栏的法则与类象依据见 `knowledge/健康与寿元.md`；实务断法层清单见 `knowledge/论命流程.md`。"),
LibraryEntry(id: 54, cat: "实务", title: "海报规格补充（2026-10-29，用户发易辰取名社手写单照片定规）", body: "照片原件：该社为周囿廷所出八字预测单（存 cases/周囿廷-取名社预测单.jpg）。用户定规，后期海报按此执行：\n- **栏目全上**：手写单一到七节全数纳入海报——一、性格；二、事业（选择/方向/建议）；三、财运；四、婚姻（选择/方向/建议/问题）；五、吉祥数；六、流年运势；七、建议（补五行逐项）。另保留头部数据区：出生信息、八字四柱、大运、流年盘、喜用神/忌神。\n- **数据更丰富多样**：数据量须超过该手写单——在七节之外叠加本系统已有数据层（回测记录、五行力量、长生/纳音/神煞、关键流年与引动点、依据链摘要等），不许比手写单还薄。\n- **排版设计美化**：栏目化卡片排版、数据可视化（力量条/时间轴/罗盘式流年图可借鉴其形），整体美观度高于手写单与现行 v3 海报。\n- 执行时点不变：先正确率达标（四靶），后出成品；本规格为达标后海报的栏目与设计标准。PDF 仍为详细版，逐条判断附完整依据链。"),
LibraryEntry(id: 55, cat: "实务", title: "设计参考图（2026-10-29，用户供图，存 refs/）", body: "- refs/合婚四看-参考图.jpg：国风手绘风——红绿撞色章节条、口诀框、五行环图，栏目化排版可借鉴（与海报规格补充的「卡片化＋可视化」同向）。\n- refs/十天干人格原型图.jpg：现代信息图风——十格卡片＋象徵图标＋关键词条，数据密度高而整齐，可借鉴其卡片网格与底部速览条。\n- 两图均为版式与视觉参考，非内容定版；内容以本系统知识库为准。"),
LibraryEntry(id: 56, cat: "破局", title: "总纲：五层法，层层标注，不得混层", body: "1. **典籍判断层（五典＋神峰通考）**：病药说本质是诊断学——病＝害用之字，药＝去病之字；药到位的途径只有原局自带（子平真诠「救应」）与岁运带来。**典籍里没有\"后天佩戴/摆放补命局\"的治疗学**；人能用的只有择时进退（等药运、避病年）。任铁樵原话：八字五行之和以岁运和之，脏腑之和以五味和之——命与身，两分。\n2. **典籍伦理层（了凡四训）**：传统内部唯一成体系的改命论。命由我作、福自己求；极善之人，数拘他不定。方法全在道德修身：改过、积善、谦德、功过格。与术数物品无关。\n3. **流派应用层**：五行补救（行业/方位/服色/饮食，源《内经》五方五色宇宙论＋喜用神框架）、风水调理（独立堪舆体系，转交风水窗主断）、八字用字改名派。可用，但须明示是应用层、非五典原文。\n4. **民间象征层**：吉祥数字（三八木/四九金/一六水/二七火/五十土，有河图根源）、水晶饰物对应、摆件清单——象征与心理层，交付时必须标注民间说法。三才五格姓名学实为日本熊崎健翁 1929 年五格剖象法回传，不得冒称宋代源流。\n5. **现实决策层**：证照、社保、财务制度、健康管理、决策规则——无命理依据需求，纯现实有效，破局方案的主体应在此层，命理层只负责定时间（哪年进、哪年退）与方向（喜忌）。"),
LibraryEntry(id: 57, cat: "破局", title: "关键考据（回源核实）", body: "- 「有病方为贵，无伤不是奇」：《滴天髓》以「虽曰」引述成说、立场节制归于中和；系统立病药说类者是明·张楠《神峰通考》——**神峰通考补入书单，为第六部**。\n- 取用五法（扶抑/病药/调候/专旺/通关）清单系民国徐乐吾《子平真诠评注》系统化，引用沈孝瞻须分沈/徐两行。\n- 穷通调候两例：金寒水冷→丙解冻、丁炼金、甲亦不可少；火炎土燥→壬癸水且须庚申金发源（无源之水不济）。\n- 「一命二运三风水」最早可考为清·文康《儿女英雄传》第三十八回俗语，原文止于「四积阴功五读书」，其后皆递增附会。"),
LibraryEntry(id: 58, cat: "破局", title: "两类盘型的流派分歧（方法论存档）", body: "- 火旺无水丙火：调候派主壬水＋金发源；格局派（论阳刃）主官杀制刃、防合去杀；专旺炎上派反主不喜水破格——取决于专旺成败，先定格再谈药。空亡按三命通会「空而有实未可便凶」，以岁运填实论应期。\n- 丁火食神生财无印：扶抑主木火帮身；格局派内部有张力——印扶身有夺食破生财链之虞，一派主印、一派忌印（帮身以比劫最稳），断语须并列呈报、结合月令。"),
LibraryEntry(id: 59, cat: "破局", title: "交付规矩", body: "破局方案按五层分段写：第 1 层只给时间表（药运何时到、病年何时避）；第 3、4 层每条标层级；第 5 层为主体。忌把民间层写成典籍层，忌「缺啥补啥」（与取用正法冲突）。"),
] }
// MARK: - 断语库（可搜索的研习条文库：类象/长生/排盘/论命/五典/健康/合婚/紫微/实务/破局）
struct LibraryView: View {
    @State private var query = ""
    @State private var cat = "全部"
    private var cats: [String] { ["全部"] + Array(Set(LibraryData.entries.map { $0.cat })).sorted() }
    private var filtered: [LibraryEntry] {
        LibraryData.entries.filter { e in
            (cat == "全部" || e.cat == cat) &&
            (query.isEmpty || e.title.contains(query) || e.body.contains(query))
        }
    }
    var body: some View {
        List {
            ForEach(filtered) { e in
                NavigationLink { LibraryDetailView(entry: e) } label: {
                    VStack(alignment: .leading, spacing: 3) {
                        HStack(spacing: 6) {
                            Text(e.cat).font(.caption2).fontWeight(.semibold).foregroundStyle(Ky.gold)
                            Text(e.title).font(.subheadline).fontWeight(.medium).foregroundStyle(Ky.ink)
                        }
                        Text(e.body).font(.caption).foregroundStyle(Ky.sub).lineLimit(2)
                    }
                }
            }
            if filtered.isEmpty { Text("没有匹配的条文，换个关键词试试。").font(.callout).foregroundStyle(Ky.sub) }
        }
        .searchable(text: $query, prompt: "搜条文（如：伤官、调候、羊刃）")
        .toolbar {
            ToolbarItem(placement: .principal) {
                Menu {
                    ForEach(cats, id: \.self) { c in Button(c) { cat = c } }
                } label: {
                    Text(cat == "全部" ? "断语库 · 全部分类" : "断语库 · \(cat)")
                        .font(.headline).foregroundStyle(Ky.ink)
                }
            }
        }
        .navigationBarTitleDisplayMode(.inline)
    }
}

struct LibraryDetailView: View {
    let entry: LibraryEntry
    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 10) {
                Text(entry.cat).font(.caption).fontWeight(.semibold).foregroundStyle(Ky.gold)
                Text(entry.body).font(.callout).foregroundStyle(Ky.ink)
                Text("来源：工作室研习知识库（五典纲要与流派应用分层标注处以原文为准）。")
                    .font(.caption2).foregroundStyle(Ky.sub)
            }.padding(16)
        }
        .background(Ky.bg)
        .navigationTitle(entry.title)
        .navigationBarTitleDisplayMode(.inline)
    }
}
